    te: 'మీ నివేదికలను స్పష్టంగా అర్థం చేసుకోండి మరియు ఆరోగ్య ఆందోళనను తగ్గించండి.',
    kn: 'ನಿಮ್ಮ ವರದಿಗಳನ್ನು ಸ್ಪಷ್ಟವಾಗಿ ಅರ್ಥಮಾಡಿಕೊಂಡು ಆರೋಗ್ಯ ಚಿಂತೆಯನ್ನು ಕಡಿಮೆ ಮಾಡಿ.',
    ml: 'നിങ്ങളുടെ റിപ്പോർട്ടുകൾ വ്യക്തമായി മനസ്സിലാക്കി ആരോഗ്യ ആശങ്ക കുറയ്ക്കുക.',
    bn: 'আপনার রিপোর্ট স্পষ্টভাবে বুঝুন এবং স্বাস্থ্য উদ্বেগ কমান।',
    gu: 'તમારા રિપોર્ટ સ્પષ્ટ રીતે સમજો અને સ્વાસ્થ્ય ચિંતા ઘટાડો.',
    mr: 'आपले अहवाल स्पष्टपणे समजून घ्या आणि आरोग्याची चिंता कमी करा.',
    pa: 'ਆਪਣੀ ਰਿਪੋਰਟ ਨੂੰ ਸਪੱਸ਼ਟ ਤੌਰ ਤੇ ਸਮਝੋ ਅਤੇ ਸਿਹਤ ਚਿੰਤਾ ਘਟਾਓ।',
