  'about.description': {
    en: 'We are a passionate team working together to build innovative AI-powered solutions that can make a positive impact. Our goal is to leverage AWS technologies and artificial intelligence to create smart, scalable, and user-friendly applications.',
    hi: 'हम एक जुनूनी टीम हैं जो साथ मिलकर नवीन AI-संचालित समाधान बनाने के लिए काम कर रही है जो सकारात्मक प्रभाव डाल सकते हैं। हमारा लक्ष्य स्मार्ट, स्केलेबल और उपयोगकर्ता-अनुकूल अनुप्रयोग बनाने के लिए AWS तकनीकों और कृत्रिम बुद्धिमत्ता का लाभ उठाना है।',
    ta: 'நாங்கள் ஒரு ஆர்வமுள்ள குழு, நேர்மறையான தாக்கத்தை ஏற்படுத்தக்கூடிய புதுமையான AI-இயக்கப்படும் தீர்வுகளை உருவாக்க ஒன்றாகப் பணியாற்றுகிறோம். ஸ்மார்ட், மேம்படுத்தக்கூடிய மற்றும் பயனர் நட்பு பயன்பாடுகளை உருவாக்க AWS தொழில்நுட்பங்களையும் செயற்கை நுண்ணறிவையும் பயன்படுத்துவதே எங்கள் இலக்கு.',
    te: 'మేము ఒక భావోద్వేగ బృందం, సానుకూల ప్రభావాన్ని చూపగల నవీన AI-ఇత�త పరిష్కారాలను నిర్మించడానికి కలిసి పనిచేస్తున్నాం. స్మార్ట్, స్కేలబుల్ మరియు వినియోగదారు స్నేహపూర్వక అప్లికేషన్‌లను సృష్టించడానికి AWS సాంకేతికతలను మరియు కృత్రిమ మేధస్సును ఉపయోగించడమే మా లక్ష్యం.',
    kn: 'ನಾವು ಒಂದು ಉತ್ಸಾಹಭರಿತ ತಂಡ, ಸಕಾರಾತ್ಮಕ ಪ್ರಭಾವ ಬೀರಬಲ್ಲ ನವೀನ AI-ಚಾಲಿತ ಪರಿಹಾರಗಳನ್ನು ನಿರ್ಮಿಸಲು ಒಟ್ಟಿಗೆ ಕೆಲಸ ಮಾಡುತ್ತಿದ್ದೇವೆ. ಸ್ಮಾರ್ಟ್, ಸ್ಕೇಲಬಲ್ ಮತ್ತು ಬಳಕೆದಾರರಿಗೆ ಸ್ನೇಹಪರವಾದ ಅಪ್ಲಿಕೇಶನ್‌ಗಳನ್ನು ರಚಿಸಲು AWS ತಂತ್ರಜ್ಞಾನಗಳು ಮತ್ತು ಕೃತ್ರಿಮ ಬುದ್ಧಿಮತ್ತೆಯನ್ನು ಬಳಸುವುದು ನಮ್ಮ ಗುರಿ.',
    ml: 'ആഴത്തിലുള്ള പ്രഭാവം സൃഷ്ടിക്കാൻ കഴിയുന്ന നൂതന AI-പ്രവർത്തിപ്പിക്കുന്ന പരിഹാരങ്ങൾ നിർമ്മിക്കാൻ ഒരുമിച്ച് പ്രവർത്തിക്കുന്ന ഒരു തീവ്രമായ ടീമാണ് ഞങ്ങൾ. സ്മാർട്ട്, സ്കേലബിൾ, ഉപയോക്തൃ സൗഹൃദ അപ്ലിക്കേഷനുകൾ സൃഷ്ടിക്കാൻ AWS സാങ്കേതികവിദ്യകളും കൃത്രിമ ബുദ്ധിയും പ്രയോജനപ്പെടുത്തുക എന്നതാണ് ഞങ്ങളുടെ ലക്ഷ്യം.',
    bn: 'আমরা একটি উত্সাহী দল, ইতিবাচক প্রভাব ফেলতে পারে এমন উদ্ভাবনী AI-চালিত সমাধান তৈরি করতে একসাথে কাজ করছি। স্মার্ট, স্কেলেবল এবং ব্যবহারকারী-বান্ধব অ্যাপ্লিকেশন তৈরি করতে AWS প্রযুক্তি এবং কৃত্রিম বুদ্ধিমত্তা ব্যবহার করা আমাদের লক্ষ্য।',
    gu: 'અમે એક ઉત્સાહી ટીમ છીએ, સકારાત્મક અસર કરી શકે તેવા નવીન AI-સંચાલિત ઉકેલો બનાવવા માટે એકસાથે કામ કરીએ છીએ. સ્માર્ટ, સ્કેલેબલ અને વપરાશકર્તા-મૈત્રીપૂર્ણ એપ્લિકેશન્સ બનાવવા માટે AWS ટેકનોલોજી અને કૃત્રિમ બુદ્ધિનો ઉપયોગ કરવો એ અમારું લક્ષ્ય છે।',
    mr: 'आम्ही एक आवेशी टीम आहोत, सकारात्मक प्रभाव टाकू शकणाऱ्या नावीन्यपूर्ण AI-चालित सोल्यूशन्स तयार करण्यासाठी एकत्र काम करत आहोत. स्मार्ट, स्केलेबल आणि वापरकर्ता-अनुकूल अनुप्रयोग तयार करण्यासाठी AWS तंत्रज्ञान आणि कृत्रिम बुद्धिमत्ता वापरणे हे आमचे ध्येय आहे।',
    pa: 'ਅਸੀਂ ਇੱਕ ਭਾਵੁਕ ਟੀਮ ਹਾਂ, ਸਕਾਰਾਤਮਕ ਪ੍ਰਭਾਵ ਪਾ ਸਕਣ ਵਾਲੇ ਨਵੀਨ AI-ਚਲਾਏ ਹੱਲ ਬਣਾਉਣ ਲਈ ਇਕੱਠੇ ਕੰਮ ਕਰ ਰਹੇ ਹਾਂ। ਸਮਾਰਟ, ਸਕੇਲੇਬਲ ਅਤੇ ਉਪਯੋਗਕਰਤਾ-ਦੋਸਤਾਨਾ ਐਪਲੀਕੇਸ਼ਨ ਬਣਾਉਣ ਲਈ AWS ਤਕਨਾਲੋਜੀ ਅਤੇ ਕ੍ਰਿਤrim ਬੁੱਧੀਮੱਤਾ ਦੀ ਵਰਤੋਂ ਕਰਨਾ ਸਾਡਾ ਲਕਸ਼ ਹੈ।',
  },
