  'privacy.dataSharing.content2': {
    en: ' sell, trade, or rent your personal health information to third parties. Your data is never shared with:',
    hi: ' तीसरे पक्षों को आपकी व्यक्तिगत स्वास्थ्य जानकारी बेचता, व्यापार करता या किराए पर देता है। आपका डेटा कभी निम्नलिखित के साथ साझा नहीं किया जाता है:',
    ta: ' உங்கள் தனிப்பட்ட சுகாதார தகவல்களை மூன்றாம் தரப்பினருக்கு விற்கவோ, வணிகம் செய்யவோ அல்லது வாடகைக்கு விடவோ இல்லை. உங்கள் தரவு ஒருபோதும் பின்வருவனவற்றுடன் பகிரப்படுவதில்லை:',
    te: ' మీ వ్యక్తిగత ఆరోగ్య సమాచారాన్ని మూడవ పక్షలకు అమ్మదు, వ್ಯాపారం చేయదు లేదా బదులుగా ఇవ్వదు. మీ డేటా ఎప్పుడూ ఇవ్వబడదు:',
    kn: ' ನಿಮ್ಮ ವೈಯಕ್ತಿಕ ಆರೋಗ್ಯ ಮಾಹಿತಿಯನ್ನು ಮೂರನೇ ಪಕ್ಷಗಳಿಗೆ ಮಾರಾಟ ಮಾಡುವುದಿಲ್ಲ, ವ್ಯಾಪಾರ ಮಾಡುವುದಿಲ್ಲ ಅಥವಾ ಬಾಡಿಗೆಗೆ ನೀಡುವುದಿಲ್ಲ. ನಿಮ್ಮ ಡೇಟಾವನ್ನು ಎಂದಿಗೂ ಹಂಚಿಕೊಳ್ಳುವುದಿಲ್ಲ:',
    ml: ' നിങ്ങളുടെ വ്യക്തിഗത ആരോഗ്യ വിവരങ്ങൾ മൂന്നാം കക്ഷികൾക്ക് വിൽക്കുകയോ, വ്യാപാരം ചെയ്യുകയോ അല്ലെങ്കിൽ വാടകയ്ക്ക് നൽകുകയോ ചെയ്യുന്നില്ല. നിങ്ങളുടെ ഡാറ്റ ഒരിക്കലും പങ്കിടുന്നില്ല:',
    bn: ' তৃতীয় পক্ষের কাছে আপনার ব্যক্তিগত স্বাস্থ্য তথ্য বিক্রি করে না, বাণিজ্য করে না বা ভাড়া দেয় না। আপনার ডেটা কখনই নিম্নলিখিতদের সাথে শেয়ার করা হয় না:',
    gu: ' ત્રીજા પક્ષોને તમારી અંગત આરોગ્ય માહિતી વેચતો નથી, વેપાર કરતો નથી અથવા ભાડે આપતો નથી. તમારો ડેટા ક્યારેય આની સાથે શેર કરવામાં આવતો નથી:',
    mr: ' तृतीय पक्षांना तुमची वैयक्तिक आरोग्य माहिती विकत नाही, व्यापार करत नाही किंवा भाड्याने देत नाही. तुमचा डेटा कधीही खालिलांशी शेअर केला जात नाही:',
    pa: " ਤੀਜੇ ਧਿਰਾਂ ਨੂੰ ਤੁਹਾਡੀ ਨਿੱਜੀ ਸਿਹਤ ਜਾਣਕਾਰੀ ਨਹੀਂ ਵੇਚਦਾ, ਵਪਾਰ ਨਹੀਂ ਕਰਦਾ ਜਾਂ ਕਿਰਾਏ 'ਤੇ ਨਹੀਂ ਦਿੰਦਾ। ਤੁਹਾਡਾ ਡੇਟਾ ਕਦੇ ਵੀ ਇਹਨਾਂ ਨਾਲ ਸਾਂਝਾ ਨਹੀਂ ਕੀਤਾ ਜਾਂਦਾ:",
  },
