  'privacy.dataSharing.content3': {
    en: 'We may only share anonymized, aggregated data for research and public health purposes, which cannot be traced back to any individual.',
    hi: 'हम केवल शोध और सार्वजनिक स्वास्थ्य उद्देश्यों के लिए गुमनाम, एकत्रित डेटा साझा कर सकते हैं, जिसे किसी भी व्यक्ति तक वापस नहीं ट्रेस किया जा सकता है।',
    ta: 'ஆராய்ச்சி மற்றும் பொது சுகாதார நோக்கங்களுக்காக அநாமதேய, திரட்டப்பட்ட தரவுகளை மட்டுமே பகிர்வோம், அவை எந்தவொரு நபருக்கும் திரும்ப கண்டறிய முடியாதவை.',
    te: 'పరిశోధన మరియు ప్రజారోగ్య ప్రయోజనాల కోసం అనామకీకరించబడిన, సమీకృత డేటాను మాత్రమే మేము పంచుకోవచ్చు, దీనిని ఏ వ్యక్తికీ తిరిగి ట్రేస్ చేయలేము.',
    kn: 'ಪ್ರಯೋಗ ಮತ್ತು ಸಾರ್ವಜನಿಕ ಆರೋಗ್ಯ ಉದ್ದೇಶಗಳಿಗಾಗಿ ಅನಾಮಧೇಯ, ಸಂಗ್ರಹಿಸಿದ ಡೇಟಾವನ್ನು ಮಾತ್ರ ನಾವು ಹಂಚಿಕೊಳ್ಳಬಹುದು, ಅದನ್ನು ಯಾವುದೇ ವ್ಯಕ್ತಿಗೆ ಹಿಂತಿರುಗಿ ಗುರುತಿಸಲು ಸಾಧ್ಯವಿಲ್ಲ.',
    ml: 'ഗവേഷണവും ന്യായമായ ആരോഗ്യ ആവശ്യങ്ങൾക്കുമായി അനാമിക, സമ്ടി ഡാറ്റ മാത്രമാണ് ഞങ്ങൾ പങ്കിടുന്നത്, അത് ഏത് വ്യക്തിയിലേക്കും തിരിച്ചെത്താൻ കഴിയില്ല.',
    bn: 'গবেষণা এবং সার্বজনীন স্বাস্থ্য উদ্দেশ্যে বেনামী, সমষ্টিগত তথ্য শেয়ার করতে পারি, যা কোনো ব্যক্তিকে ট্রেস করা যাবে না।',
    gu: 'અમે ફક્ત સંશોધન અને જાહેર આરોગ્ય હેતુઓ માટે અનામી, એકત્રિત ડેટા શેર કરી શકીએ છીએ, જે કોઈપણ વ્યક્તિને ટ્રેસ કરી શકાતો નથી.',
    mr: 'आम्ही फक्त संशोधन आणि सार्वजनिक आरोग्य उद्देश्यांसाठी अनामी, एकत्रित डेटा शेअर करू शकतो, जो कोणत्याही व्यक्तीला ट्रेस करता येत नाही.',
    pa: 'ਅਸੀਂ ਸਿਰਫ਼ ਖੋਜ ਅਤੇ ਜਨਤਕ ਸਿਹਤ ਦੇ ਉਦੇਸ਼ਾਂ ਲਈ ਅਗਿਆਤ, ਇਕੱਠਾ ਡੇਟਾ ਸਾਂਝਾ ਕਰ ਸਕਦੇ ਹਾਂ, ਜੋ ਕਿਸੇ ਵੀ ਵਿਅਕਤੀ ਨੂੰ ਟ੍ਰੇਸ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਦਾ।',
  },
