    bn: 'বিশ্লেষণের জন্য মেডিকেল নথির স্পষ্ট, পাঠযোগ্য কপি প্রদান করুন',
    gu: 'વિશ્લેષણ માટે તબીબી દસ્તાવેજોના સ્પષ્ટ, વાંચી શકાય તેવી નકલો પૂરી પાડો',
    mr: 'विश्लेषणासाठी वैद्यकीय दस्तऐवजांच्या स्पष्ट, वाचता येण्याजोग्या प्रती पुरवा',
    pa: 'ਵਿਸ਼ਲੇਸ਼ਣ ਲਈ ਮੈਡੀਕਲ ਦਸਤਾਵੇਜ਼ਾਂ ਦੀਆਂ ਸਪੱਸ਼ਟ, ਪੜ੍ਹਨ ਯੋਗ ਕਾਪੀਆਂ ਪ੍ਰਦਾਨ ਕਰੋ',
