    ml: 'നിങ്ങളുടെ ആരോഗ്യ സേവാ ദാതാക്കൾക്ക് ബന്ധപ്പെട്ട എല്ലാ മെഡിക്കൽ ചരിത്രവും വെളിപ്പെടുത്തുക',
    bn: 'আপনার স্বাস্থ্যসেবা প্রদানকারীদের কাছে সমস্ত প্রাসঙ্গিক চিকিৎসা ইতিহাস প্রকাশ করুন',
    gu: 'તમારા આરોગ્ય સેવા પ્રદાતાઓને તમારો બધો સંબંધિત તબીબી ઇતિહાસ જણાવો',
    mr: 'तुमच्या आरोग्य सेवा प्रदात्यांना संबंधित वैद्यकीय इतिहास सांगा',
    pa: 'ਆਪਣੇ ਸਿਹਤ ਸੇਵਾ ਪ੍ਰਦਾਤਾਵਾਂ ਨੂੰ ਸਾਰਾ ਸਬੰਧਿਤ ਮੈਡੀਕਲ ਇਤਿਹਾਸ ਦੱਸੋ',
