    gu: 'તબીબી નિર્ણયો માટે ફક્ત AI-જનરેટેડ માહિતી પર જ ભરોસો ન કરો',
    mr: 'वैद्यकीय निर्णयांसाठी फक्त AI-व्युत्पन्न माहितीवर अवलंबून राहू नका',
